const homeDirectory = [
  {id:'foxglove',name:'Foxglove House',type:'Children’s Services',region:'Profile to be confirmed',image:'https://images.unsplash.com/photo-1564013799919-ab600027ffc6?auto=format&fit=crop&w=1100&q=85',label:'Home profile preview',text:'A place for stability, trusted relationships and everyday moments that matter.',tags:['Nurturing environment','Individual support'],status:'profile'},
  {id:'skyline',name:'Skyline Child Care',type:'Children’s Services',region:'West Midlands',image:'https://images.unsplash.com/photo-1511895426328-dc8714191300?auto=format&fit=crop&w=1100&q=85',label:'Explore the service',text:'Discover Skyline’s approach to residential care for children and young people.',tags:['Residential care','Children & young people'],status:'external'},
  {id:'willow',name:'Willow Gardens',type:'Older Persons',region:'Illustrative · South East',image:'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?auto=format&fit=crop&w=1100&q=85',label:'Future acquisition · demo',text:'A welcoming setting imagined around familiar routines, comfort and connection.',tags:['Older persons','Everyday wellbeing'],status:'demo'},
  {id:'cedar',name:'Cedar Lodge',type:'Learning Disabilities & Autism',region:'Illustrative · Midlands',image:'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1100&q=85',label:'Future acquisition · demo',text:'An imagined support setting where choice, community and independence come first.',tags:['Personal goals','Community connection'],status:'demo'},
  {id:'meadow',name:'Meadow View',type:'Children’s Services',region:'Illustrative · North West',image:'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=1100&q=85',label:'Future acquisition · demo',text:'A homely concept with space to feel safe, build confidence and grow.',tags:['Belonging','Nurturing spaces'],status:'demo'},
  {id:'oak',name:'Oak House',type:'Older Persons',region:'Illustrative · South West',image:'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1100&q=85',label:'Future acquisition · demo',text:'A future-home concept bringing thoughtful interiors and meaningful everyday life together.',tags:['Comfort & choice','Family connection'],status:'demo'}
];
let homesFilter='All services', homesQuery='', homesSavedOnly=false;
let homesSaved=new Set();
try { const saved=JSON.parse(localStorage.getItem('pinar-homes-shortlist')||'[]'); if(Array.isArray(saved)) homesSaved=new Set(saved.filter(id=>homeDirectory.some(h=>h.id===id))); } catch {}
const homesPage=()=>`<div class="homes-page"><section class="directory-hero"><div><span class="eyebrow">Our Homes & services</span><h1>A place to feel<br><em>you belong.</em></h1><p>Every person’s idea of home is different. Explore our settings and find the right starting point for a conversation.</p><a class="pill-btn" href="#/our-homes" data-home-browse>Explore the collection <span>↓</span></a></div><div class="directory-hero-photo"><img src="https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1400&q=85" alt="Illustrative warm living room with natural light"><span>Room for the life<br>you want to lead.</span></div></section>
<section class="directory-section" aria-labelledby="collection-title"><div class="directory-heading"><div><span class="eyebrow">Find your setting</span><h2 id="collection-title">Care that fits.<br>A home that feels right.</h2></div><p>Browse by service or search by name and area. Save a few favourites to revisit together.</p></div><div class="directory-demo"><span aria-hidden="true">✧</span><p><strong>A glimpse of what comes next.</strong> Cards marked “Future acquisition · demo” are fictional examples, not announced acquisitions or operating Pinar homes. All directory photos are illustrative. Availability and support details require confirmation.</p></div>
<div class="directory-controls"><label class="home-search"><span>Search homes or areas</span><input id="home-search" type="search" placeholder="Try a home name or area" autocomplete="off"></label><button class="shortlist-toggle" type="button" aria-pressed="false">♡ My shortlist <span data-saved-count>0</span></button></div><div class="home-filters" role="group" aria-label="Filter by service">${['All services','Older Persons','Learning Disabilities & Autism','Children’s Services'].map(t=>`<button type="button" data-home-filter="${t}" aria-pressed="${t==='All services'}">${t}</button>`).join('')}</div><div class="directory-results"><p id="home-result-count" role="status" aria-live="polite"></p><button class="home-reset" type="button">Reset filters</button></div><div class="directory-grid" id="home-results"></div></section><section class="directory-help"><div><span class="eyebrow">Let’s talk it through</span><h2>Not sure where<br>to begin?</h2><p>Tell us what matters to you. We can help you explore the next step.</p></div><div><button class="pill-btn" data-placeholder="Talk to our team">Talk to our team <span>↗</span></button><button class="outline-btn" data-placeholder="Referrals">Make a referral</button><p>Future acquisition examples are for design review only and do not accept referrals.</p></div></section></div>`;
function homeCard(h){const saved=homesSaved.has(h.id);return `<article class="directory-card"><div class="directory-card-photo"><img src="${h.image}" alt="Illustrative photograph for ${h.name}; not the actual setting" loading="lazy"><span class="home-status ${h.status==='demo'?'is-demo':''}">${h.label}</span><button type="button" class="home-save" data-home-save="${h.id}" aria-pressed="${saved}" aria-label="${saved?'Remove':'Save'} ${h.name} ${saved?'from':'to'} shortlist">${saved?'♥':'♡'}</button></div><div class="directory-card-copy"><span class="home-type">${h.type}</span><h3>${h.name}</h3><p class="home-area">${h.region}</p><p>${h.text}</p><div class="home-tags">${h.tags.map(t=>`<span>${t}</span>`).join('')}</div>${h.status==='external'?'<a class="home-card-link" href="https://skylinechildcare.com/" target="_blank" rel="noopener noreferrer">Explore Skyline <span>↗</span></a>':`<button type="button" class="home-card-link" data-home-detail="${h.id}">${h.status==='demo'?'Preview concept':'Explore Foxglove House'} <span>↗</span></button>`}</div></article>`;}
function updateHomeResults(){const q=homesQuery.toLowerCase().trim();const filtered=homeDirectory.filter(h=>(homesFilter==='All services'||h.type===homesFilter)&&(!homesSavedOnly||homesSaved.has(h.id))&&(!q||[h.name,h.type,h.region,...h.tags].join(' ').toLowerCase().includes(q)));const results=document.getElementById('home-results');if(!results)return;results.innerHTML=filtered.length?filtered.map(homeCard).join(''):'<div class="homes-empty"><h3>No settings match just yet.</h3><p>Try another name, choose a different service or reset your filters.</p><button class="outline-btn" type="button" data-home-empty-reset>Show all settings</button></div>';document.getElementById('home-result-count').textContent=`${filtered.length} ${filtered.length===1?'setting':'settings'}${homesSavedOnly?' in your shortlist':''} · includes design previews`;document.querySelector('[data-saved-count]').textContent=homesSaved.size;document.querySelector('.shortlist-toggle').setAttribute('aria-pressed',String(homesSavedOnly));document.querySelectorAll('[data-home-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.homeFilter===homesFilter)));}
function resetHomes(){homesFilter='All services';homesQuery='';homesSavedOnly=false;document.getElementById('home-search').value='';updateHomeResults();}
function wireHomes(){if(!document.getElementById('home-results'))return;homesFilter='All services';homesQuery='';homesSavedOnly=false;updateHomeResults();document.getElementById('home-search').addEventListener('input',e=>{homesQuery=e.target.value;updateHomeResults();});document.querySelector('.directory-section').addEventListener('click',e=>{const filter=e.target.closest('[data-home-filter]');if(filter){homesFilter=filter.dataset.homeFilter;updateHomeResults();}if(e.target.closest('.shortlist-toggle')){homesSavedOnly=!homesSavedOnly;updateHomeResults();}if(e.target.closest('.home-reset,[data-home-empty-reset]'))resetHomes();const save=e.target.closest('[data-home-save]');if(save){const id=save.dataset.homeSave;homesSaved.has(id)?homesSaved.delete(id):homesSaved.add(id);try{localStorage.setItem('pinar-homes-shortlist',JSON.stringify([...homesSaved]));}catch{}updateHomeResults();const next=document.querySelector(`[data-home-save="${id}"]`);if(next)next.focus();else document.querySelector('.shortlist-toggle').focus();}const detail=e.target.closest('[data-home-detail]');if(detail){const h=homeDirectory.find(h=>h.id===detail.dataset.homeDetail);showPlaceholder(h.name);document.getElementById('dialog-copy').textContent=h.status==='demo'?`${h.name} is a fictional future-acquisition concept for design review. It is not an operating Pinar Care home, a confirmed acquisition or an available placement. The name, area, imagery and service description are illustrative.`:'Foxglove House is included as a home-profile entry point. A separate detail page will follow with verified photography, support information and referral guidance.';}});document.querySelector('[data-home-browse]').onclick=e=>{e.preventDefault();document.querySelector('.directory-section').scrollIntoView({behavior:'smooth'});};}
